	}
	rt.DB.Close()
	if w:=request(h,"GET","/dashboard/api/overview");w.Code!=503||strings.Contains(w.Body.String(),"sqlite") { t.Fatalf("unsafe storage error: %d %s",w.Code,w.Body.String()) }
}

