  .events td:first-child { grid-area: 1 / 1; width: auto; }
  .events td:nth-child(2) { grid-area: 2 / 1 / auto / 3; padding: 4px 0 8px; }
  .events td:nth-child(3) { grid-area: 3 / 1 / auto / 3; width: auto; }
  .events td:last-child:not(:first-child) { grid-area: 1 / 2; width: auto; font-size: .75rem; }
  .events .secondary { display: inline; margin-left: 8px; }
  .events td.empty { grid-column: 1 / -1; padding: 20px 10px; }
  .event-open { min-height: 36px; }
  .timings tr { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); padding: 12px 0; gap: 12px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
  .timings td { padding: 0; border: 0; }
  .timings td:first-child { grid-column: 1 / -1; max-width: none; min-width: 0; }
  .timings td:not(:first-child) { text-align: left; }
  .timings td[data-label]::before { content: attr(data-label); display: block; color: var(--muted); font-size: .6875rem; font-weight: 400; margin-bottom: 3px; }
  .detail { padding: 16px; }
  .detail .section-heading { flex-wrap: nowrap; }
  .pagination { gap: 8px; }
  .pagination button { padding: 8px 10px; }
}

